INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9101, 'បើ \(\Delta ABC \cong \Delta DEF\) នោះធាតុត្រូវគ្នារវាងត្រីកោណទាំងពីរមានចំនួនប៉ុន្មានគូ?', NULL, '["\\(5\\ \\text{គូ}\\)", "\\(4\\ \\text{គូ}\\)", "\\(6\\ \\text{គូ}\\)", "\\(3\\ \\text{គូ}\\)"]', 2, NULL, 1, 'mcq', 'ត្រីកោណពីរប៉ុនគ្នាមានធាតុត្រូវគ្នា ៦ គូ គឺជ្រុងត្រូវគ្នា ៣ គូ និងមុំត្រូវគ្នា ៣ គូ។', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9102, 'ករណីប៉ុនគ្នានៃត្រីកោណ "ជ.ម.ជ" សំដៅលើលក្ខខណ្ឌណា?', NULL, '["\\(\\text{ជ្រុងទាំងបីប៉ុនគ្នា}\\)", "\\(\\text{ជ្រុងពីរនិងមុំមួយណាក៏បាន}\\)", "\\(\\text{មុំពីរនិងជ្រុងមួយ}\\)", "\\(\\text{ជ្រុងពីរនិងមុំផ្គុំដោយជ្រុងទាំងពីរប៉ុនរៀងគ្នា}\\)"]', 3, NULL, 1, 'mcq', 'ជ.ម.ជ (Side-Angle-Side) គឺមុំមួយប៉ុនគ្នាអមដោយជ្រុងពីរប៉ុនរៀងគ្នា។', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9103, 'ត្រីកោណកែងពីរប៉ុនគ្នាតាមករណី "អ.ម" កាលណាវាមាន ៖', NULL, '["\\(\\text{អ៊ីប៉ូតេនុសប៉ុនគ្នានិងមុំស្រួចមួយប៉ុនគ្នា}\\)", "\\(\\text{អ៊ីប៉ូតេនុសស្មើជ្រុងមុំកែង}\\)", "\\(\\text{ជ្រុងមុំកែងពីរប៉ុនគ្នា}\\)", "\\(\\text{មុំកែងពីរស្មើគ្នា}\\)"]', 0, NULL, 1, 'mcq', 'អ.ម គឺអ៊ីប៉ូតេនុសប៉ុនគ្នានិងមុំស្រួចមួយប៉ុនគ្នា។', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9104, 'ក្នុងត្រីកោណមួយ ប្រវែងជ្រុងមួយតែងតែ ៖', NULL, '["\\(\\text{តូចជាងផលបូកជ្រុងពីរទៀត}\\)", "\\(\\text{ធំជាងផលបូកជ្រុងពីរទៀត}\\)", "\\(\\text{ស្មើផលបូកជ្រុងពីរទៀត}\\)", "\\(\\text{ស្មើផលគុណជ្រុងពីរទៀត}\\)"]', 0, NULL, 1, 'mcq', 'ទ្រឹស្តីបទវិសមភាពត្រីកោណ ៖ ផលបូកប្រវែងជ្រុងពីរតែងតែធំជាងជ្រុងទីបី នាំឱ្យជ្រុងមួយតូចជាងផលបូកជ្រុងពីរទៀត។', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
