INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9110, 'ករណីប៉ុនគ្នានៃត្រីកោណ "ម.ជ.ម" សំដៅលើលក្ខខណ្ឌណា?', NULL, '["\\(\\text{មុំបីប៉ុនគ្នា}\\)", "\\(\\text{ជ្រុងមួយនិងមុំជាប់ជ្រុងនោះពីរប៉ុនរៀងគ្នា}\\)", "\\(\\text{ជ្រុងពីរនិងមុំមួយ}\\)", "\\(\\text{ជ្រុងទាំងបីប៉ុនគ្នា}\\)"]', 1, NULL, 1, 'mcq', 'ម.ជ.ម (Angle-Side-Angle) គឺជ្រុងមួយប៉ុនគ្នាជាប់នឹងមុំពីរប៉ុនរៀងគ្នា។', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
