INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9111, 'ត្រីកោណ \(ABC\) និង \(DEF\) មាន \(AB = DE = 5\ \text{cm}\), \(AC = DF = 7\ \text{cm}\) និង \(\angle A = \angle D = 60^\circ\)។ ត្រីកោណទាំងពីរប៉ុនគ្នាតាមករណី ៖', 'g8-d471395312.svg', '["\\(\\text{ម.ជ.ម}\\)", "\\(\\text{ជ.ជ.ជ}\\)", "\\(\\text{អ.ម}\\)", "\\(\\text{ជ.ម.ជ}\\)"]', 3, NULL, 2, 'mcq', 'មានជ្រុងពីរ និងមុំផ្គុំដោយជ្រុងទាំងពីរប៉ុនគ្នា នាំឱ្យប៉ុនគ្នាតាម ជ.ម.ជ (SAS)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9112, 'ត្រីកោណ \(PQR\) និង \(STU\) មាន \(\angle P = \angle S = 45^\circ\), \(\angle Q = \angle T = 65^\circ\) និង \(PQ = ST = 8\ \text{cm}\)។ ត្រីកោណទាំងពីរប៉ុនគ្នាតាម ៖', NULL, '["\\(\\text{ជ.ម.ជ}\\)", "\\(\\text{អ.ជ}\\)", "\\(\\text{ជ.ជ.ជ}\\)", "\\(\\text{ម.ជ.ម}\\)"]', 3, NULL, 2, 'mcq', 'មានជ្រុងមួយជាប់នឹងមុំពីរប៉ុនរៀងគ្នា នាំឱ្យប៉ុនគ្នាតាម ម.ជ.ម (ASA)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9113, 'ត្រីកោណពីរមានរង្វាស់ជ្រុងរៀងគ្នា \(4\ \text{cm},\ 6\ \text{cm},\ 8\ \text{cm}\) និង \(4\ \text{cm},\ 6\ \text{cm},\ 8\ \text{cm}\)។ ត្រីកោណទាំងពីរប៉ុនគ្នាតាម ៖', NULL, '["\\(\\text{ជ.ម.ជ}\\)", "\\(\\text{ជ.ជ.ជ}\\)", "\\(\\text{អ.ម}\\)", "\\(\\text{ម.ជ.ម}\\)"]', 1, NULL, 2, 'mcq', 'ជ្រុងទាំងបីប៉ុនរៀងគ្នា នាំឱ្យប៉ុនគ្នាតាម ជ.ជ.ជ (SSS)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9114, 'បើ \(\Delta ABC \cong \Delta DEF\) ដោយ \(BC = 2x + 30\) និង \(EF = 5x - 90\) នោះប្រវែង \(BC\) ស្មើ ៖', NULL, '["\\(80\\ \\text{cm}\\)", "\\(120\\ \\text{cm}\\)", "\\(40\\ \\text{cm}\\)", "\\(110\\ \\text{cm}\\)"]', 3, NULL, 2, 'mcq', '\(2x + 30 = 5x - 90 \Rightarrow 3x = 120 \Rightarrow x = 40\) នាំឱ្យ \(BC = 2(40) + 30 = 110\ \text{cm}\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
