INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9115, 'ត្រីកោណកែងពីរ \(ABC\) និង \(DEF\) កែងត្រង់ \(A\) និង \(D\) មាន \(AB = DE\) និងអ៊ីប៉ូតេនុស \(BC = EF\)។ ត្រីកោណទាំងពីរប៉ុនគ្នាតាម ៖', 'g8-f9b74f4703.svg', '["\\(\\text{អ.ម}\\)", "\\(\\text{ម.ជ.ម}\\)", "\\(\\text{ជ.ម.ជ}\\)", "\\(\\text{អ.ជ}\\)"]', 3, NULL, 2, 'mcq', 'មានអ៊ីប៉ូតេនុសប៉ុនគ្នា និងជ្រុងមុំកែងមួយប៉ុនគ្នា នាំឱ្យប៉ុនគ្នាតាម អ.ជ (Hypotenuse-Leg)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9116, 'ក្នុង \(\Delta ABC\) មាន \(\angle A = 80^\circ\), \(\angle B = 60^\circ\) និង \(\angle C = 40^\circ\)។ ជ្រុងដែលវែងជាងគេគឺ ៖', NULL, '["\\(\\text{ជ្រុងទាំងបីស្មើគ្នា}\\)", "\\(AB\\)", "\\(BC\\)", "\\(AC\\)"]', 2, NULL, 2, 'mcq', 'ជ្រុងឈមនឹងមុំធំជាងគេ (\(\angle A = 80^\circ\)) គឺជាជ្រុងវែងជាងគេ គឺជ្រុង \(BC\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9117, 'ក្នុងចំណោមប្រវែងជ្រុងខាងក្រោម តើមួយណាអាចបង្កើតបានជាត្រីកោណ?', NULL, '["\\(4.1,\\ 4.7,\\ 9\\)", "\\(11,\\ 12,\\ 17\\)", "\\(1,\\ 2,\\ 3\\)", "\\(2,\\ 3,\\ 6\\)"]', 1, NULL, 2, 'mcq', '\(11 + 12 = 23 > 17\) (ផលបូកពីរជ្រុងតូចធំជាងជ្រុងវែងបំផុត) នាំឱ្យសង់ត្រីកោណបាន។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
