INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9118, 'បើ \(AH \perp \Delta\) ត្រង់ \(H\) ហើយចំណុច \(B, C\) នៅលើ \(\Delta\) ដោយ \(HB = 4\ \text{cm}\) និង \(HC = 6\ \text{cm}\) នោះ ៖', 'g8-99ea78665e.svg', '["\\(AB > AC\\)", "\\(AB < AC\\)", "\\(AC < AH\\)", "\\(AB = AC\\)"]', 1, NULL, 2, 'mcq', 'អង្កត់ទ្រេតណាមានគម្លាត (ចំណោលកែង) ធំជាង គឺវែងជាង នាំឱ្យ \(AB < AC\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9119, 'ត្រីកោណសមបាត \(ABC\) មានកំពូល \(A\) និងមុំកំពូល \(\angle A = 50^\circ\)។ រង្វាស់មុំបាត \(\angle B\) ស្មើ ៖', NULL, '["\\(70^\\circ\\)", "\\(50^\\circ\\)", "\\(60^\\circ\\)", "\\(65^\\circ\\)"]', 3, NULL, 2, 'mcq', '\(\angle B = \dfrac{180^\circ - 50^\circ}{2} = \dfrac{130^\circ}{2} = 65^\circ\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9120, 'ត្រីកោណសម័ង្សជាត្រីកោណដែលមានជ្រុងទាំងបីប៉ុនគ្នា។ រង្វាស់មុំនីមួយៗនៃត្រីកោណសម័ង្សស្មើ ៖', NULL, '["\\(60^\\circ\\)", "\\(180^\\circ\\)", "\\(90^\\circ\\)", "\\(45^\\circ\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{180^\circ}{3} = 60^\circ\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9121, 'បើ \(\Delta ABC \cong \Delta MNP\) ដោយ \(\angle A = 3x + 15^\circ\) និង \(\angle M = 75^\circ\) នោះតម្លៃនៃ \(x\) ស្មើ ៖', NULL, '["\\(25^\\circ\\)", "\\(20^\\circ\\)", "\\(30^\\circ\\)", "\\(15^\\circ\\)"]', 1, NULL, 2, 'mcq', '\(3x + 15^\circ = 75^\circ \Rightarrow 3x = 60^\circ \Rightarrow x = 20^\circ\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9122, 'ក្នុង \(\Delta MNP\) មាន \(MN = 7\ \text{cm}\), \(NP = 9\ \text{cm}\) និង \(MP = 5\ \text{cm}\)។ មុំដែលតូចជាងគេគឺ ៖', NULL, '["\\(\\angle N\\)", "\\(\\angle P\\)", "\\(\\angle M = \\angle P\\)", "\\(\\angle M\\)"]', 0, NULL, 2, 'mcq', 'មុំឈមនឹងជ្រុងខ្លីជាងគេ (\(MP = 5\ \text{cm}\)) គឺជាមុំតូចជាងគេ គឺមុំ \(\angle N\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9123, 'ក្នុងចំណោមប្រវែងជ្រុងខាងក្រោម តើមួយណាមិនអាចបង្កើតជាត្រីកោណបាន?', NULL, '["\\(3,\\ 4,\\ 5\\)", "\\(1,\\ 2,\\ 3\\)", "\\(5,\\ 6,\\ 7\\)", "\\(7,\\ 8,\\ 9\\)"]', 1, NULL, 2, 'mcq', '\(1 + 2 = 3\) (ផលបូកស្មើនឹងជ្រុងទីបី ចំណុចរត់ត្រង់ជួរគ្នា) មិនអាចបង្កើតជាត្រីកោណបានឡើយ។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9124, 'បើ \(AH \perp \Delta\) ត្រង់ \(H\) ហើយអង្កត់ទ្រេតពីរ \(AB = AC\) នោះគម្លាត \(HB\) និង \(HC\) ៖', NULL, '["\\(HB < HC\\)", "\\(HB + HC = AH\\)", "\\(HB = HC\\)", "\\(HB > HC\\)"]', 2, NULL, 2, 'mcq', 'អង្កត់ទ្រេតពីរប៉ុនគ្នា នាំឱ្យមានគម្លាតស្មើគ្នា ៖ \(HB = HC\)។', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9125, 'ក្នុង \(\Delta ABC\) មាន \(\angle A = 6x + 4^\circ\), \(\angle B = 7x + 12^\circ\) និង \(\angle C = 6x - 7^\circ\)។ លំដាប់ជ្រុងពីធំទៅតូចគឺ ៖', NULL, '["\\(AC > BC > AB\\)", "\\(BC > AC > AB\\)", "\\(AC > AB > BC\\)", "\\(AB > BC > AC\\)"]', 0, NULL, 3, 'mcq', '\(19x + 9 = 180 \Rightarrow x = 9^\circ\) នាំឱ្យ \(\angle B = 75^\circ > \angle A = 58^\circ > \angle C = 47^\circ\) ដូចនេះ \(AC > BC > AB\)។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9126, 'ត្រីកោណមួយមានប្រវែងជ្រុងពីរគឺ \(5\ \text{cm}\) និង \(9\ \text{cm}\)។ ប្រវែងជ្រុងទីបី \(x\) ត្រូវផ្ទៀងផ្ទាត់ ៖', NULL, '["\\(4 < x < 14\\)", "\\(x > 4\\)", "\\(x < 14\\)", "\\(5 < x < 9\\)"]', 0, NULL, 3, 'mcq', 'តាមវិសមភាពត្រីកោណ \(9 - 5 < x < 9 + 5 \Rightarrow 4 < x < 14\)។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9127, 'ចំណុចប្រសព្វនៃកន្លះបន្ទាត់ពុះមុំក្នុងទាំងបីនៃត្រីកោណមួយ ឋិតនៅស្មើចម្ងាយពី ៖', NULL, '["\\(\\text{មេដ្យានទាំងបី}\\)", "\\(\\text{កម្ពស់ទាំងបី}\\)", "\\(\\text{ជ្រុងទាំងបីនៃត្រីកោណ}\\)", "\\(\\text{កំពូលទាំងបីនៃត្រីកោណ}\\)"]', 2, NULL, 3, 'mcq', 'កន្លះបន្ទាត់ពុះមុំទាំងបីប្រសព្វគ្នាត្រង់ផ្ចិតរង្វង់ចារឹកក្នុងត្រីកោណ ដែលមានចម្ងាយស្មើគ្នាពីជ្រុងទាំងបី។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9128, 'ចំណុចប្រសព្វនៃមេដ្យាទ័រជ្រុងទាំងបីនៃត្រីកោណមួយ ឋិតនៅស្មើចម្ងាយពី ៖', NULL, '["\\(\\text{បន្ទាត់ពុះមុំ}\\)", "\\(\\text{កំពូលទាំងបីនៃត្រីកោណ}\\)", "\\(\\text{កម្ពស់ទាំងបី}\\)", "\\(\\text{ជ្រុងទាំងបីនៃត្រីកោណ}\\)"]', 1, NULL, 3, 'mcq', 'មេដ្យាទ័រជ្រុងទាំងបីប្រសព្វគ្នាត្រង់ផ្ចិតរង្វង់ចារឹកក្រៅត្រីកោណ ដែលស្មើចម្ងាយពីកំពូលទាំងបី (\(OA = OB = OC\))។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9129, 'អង្កត់ \(AB\) និង \(CD\) កាត់គ្នាត្រង់ចំណុចកណ្តាល \(E\) នៃអង្កត់នីមួយៗ។ ត្រីកោណ \(EAD\) និង \(EBC\) ប៉ុនគ្នាតាម ៖', NULL, '["\\(\\text{អ.ម}\\)", "\\(\\text{ម.ជ.ម}\\)", "\\(\\text{ជ.ជ.ជ}\\)", "\\(\\text{ជ.ម.ជ}\\)"]', 3, NULL, 3, 'mcq', '\(EA = EB, ED = EC\) និង \(\angle AED = \angle BEC\) (មុំទល់កំពូល) នាំឱ្យប៉ុនគ្នាតាម ជ.ម.ជ។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9130, 'ត្រីកោណកែងពីរ \(ABC\) និង \(DEF\) (កែងត្រង់ \(A\) និង \(D\)) មានអ៊ីប៉ូតេនុស \(BC = EF = 10\ \text{cm}\) និងជ្រុងមុំកែង \(AB = DE = 6\ \text{cm}\)។ ប្រវែងជ្រុង \(AC\) ស្មើ ៖', NULL, '["\\(4\\ \\text{cm}\\)", "\\(16\\ \\text{cm}\\)", "\\(6\\ \\text{cm}\\)", "\\(8\\ \\text{cm}\\)"]', 3, NULL, 3, 'mcq', '\(AC = \sqrt{10^2 - 6^2} = \sqrt{64} = 8\ \text{cm}\)។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9131, 'ក្នុងចតុកោណរាងខ្លែង \(ABCD\) មាន \(AB = BC\) និង \(AD = CD\)។ អង្កត់ទ្រូង \(BD\) មានលក្ខណៈ ៖', NULL, '["\\(\\text{ស្របនឹង } AC\\)", "\\(\\text{មិនកែងនឹង } AC\\)", "\\(\\text{ស្មើនឹង } AC\\)", "\\(\\text{ជាបន្ទាត់ពុះមុំ } \\angle B \\text{ និង } \\angle D \\text{ ហើយកែងនឹង } AC\\)"]', 3, NULL, 3, 'mcq', '\(\Delta ABD \cong \Delta CBD\) (ជ.ជ.ជ) នាំឱ្យ \(BD\) ជាបន្ទាត់ពុះមុំ និងជាមេដ្យាទ័រនៃ \(AC\)។', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
