INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9132, 'វិស្វករម្នាក់វាស់ទទឹងទន្លេ \(AB\) ដោយបង្កើតត្រីកោណ \(\Delta OAB \cong \Delta OCD\) (ដូចរូប)។ បើគាត់វាស់បាន \(CD = 45\ \text{m}\) នោះទទឹងទន្លេ \(AB\) ស្មើ ៖', 'g8-39f837a312.svg', '["\\(50\\ \\text{m}\\)", "\\(22.5\\ \\text{m}\\)", "\\(90\\ \\text{m}\\)", "\\(45\\ \\text{m}\\)"]', 3, NULL, 3, 'mcq', 'ដោយ \(\Delta OAB \cong \Delta OCD\) នាំឱ្យជ្រុងត្រូវគ្នា \(AB = CD = 45\ \text{m}\)។', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9133, 'ជាងឈើមានកំណាត់ឈើ ៤ ប្រវែង \(2\ \text{m},\ 4.5\ \text{m},\ 5.8\ \text{m}\) និង \(10.2\ \text{m}\)។ ចំនួនត្រីកោណផ្សេងគ្នាដែលអាចផ្គុំបានគឺ ៖', NULL, '["\\(2\\ \\text{ត្រីកោណ}\\)", "\\(1\\ \\text{ត្រីកោណ}\\)", "\\(4\\ \\text{ត្រីកោណ}\\)", "\\(3\\ \\text{ត្រីកោណ}\\)"]', 0, NULL, 3, 'mcq', 'បន្សំផ្ទៀងផ្ទាត់វិសមភាពត្រីកោណមានតែ ២ គឺ \(\{2, 4.5, 5.8\}\) និង \(\{4.5, 5.8, 10.2\}\)។', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9134, 'គ្រោងដំបូលផ្ទះរាងត្រីកោណសមបាត \(ABC\) មានមុំកំពូល \(\angle A = 120^\circ\)។ មុំបាតជម្រាលដំបូលនីមួយៗស្មើ ៖', NULL, '["\\(25^\\circ\\)", "\\(60^\\circ\\)", "\\(45^\\circ\\)", "\\(30^\\circ\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac{180^\circ - 120^\circ}{2} = 30^\circ\)។', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9135, 'ក្នុងវិស្វកម្មស្ពានដែក គេតែងប្រើរចនាសម្ព័ន្ធត្រីកោណ (Truss) ពីព្រោះ ៖', NULL, '["\\(\\text{ត្រីកោណមានរាងរឹងមាំមិនប្រែប្រួលតាមលក្ខណៈ ជ.ជ.ជ}\\)", "\\(\\text{ត្រីកោណងាយស្រួលបត់បែន}\\)", "\\(\\text{ត្រីកោណមានទម្ងន់ធ្ងន់ជាងគេ}\\)", "\\(\\text{ត្រីកោណសន្សំសំចៃដែកជាងគេ}\\)"]', 0, NULL, 3, 'mcq', 'តាមលក្ខណៈ ជ.ជ.ជ កាលណាជ្រុងទាំងបីថេរ រូបរាងត្រីកោណមិនអាចប្រែប្រួលរាងឡើយ (Triangle Rigidity)។', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9136, 'សិស្សានុសិស្សបោះជំរំនៅចំណុច \(A\) និង \(B\) នៅសងខាងអូរមួយ។ ពួកគេវាស់ចម្ងាយតាមត្រីកោណប៉ុនគ្នាបាន \(A''B'' = 28.5\ \text{m}\)។ ចម្ងាយ \(AB\) ពិតប្រាកដគឺ ៖', NULL, '["\\(57\\ \\text{m}\\)", "\\(14.25\\ \\text{m}\\)", "\\(30\\ \\text{m}\\)", "\\(28.5\\ \\text{m}\\)"]', 3, NULL, 3, 'mcq', 'ជ្រុងត្រូវគ្នានៃត្រីកោណប៉ុនគ្នាមានប្រវែងស្មើគ្នា ៖ \(AB = A''B'' = 28.5\ \text{m}\)។', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 1, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9137, 'គេឱ្យ \(\Delta ABC \cong \Delta DEF\) ដែលជ្រុង \(BC = 2x + 30\ \text{cm}\) និង \(EF = 5x - 90\ \text{cm}\)។ ក. ពន្យល់ហេតុអ្វី \(BC = EF\)។ ខ. កំណត់តម្លៃនៃ \(x\)។ គ. គណនាប្រវែងជ្រុង \(BC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ដោយ \(\Delta ABC \cong \Delta DEF\) នោះជ្រុងត្រូវគ្នាប៉ុនរៀងគ្នា នាំឱ្យ \(BC = EF\) (1 ពិន្ទុ)
ខ. សមីការ ៖ \(2x + 30 = 5x - 90 \Rightarrow 5x - 2x = 30 + 90\) (1 ពិន្ទុ)
\(3x = 120 \Rightarrow x = 40\) (1 ពិន្ទុ)
គ. គណនាប្រវែង \(BC = 2(40) + 30 = 80 + 30 = 110\ \text{cm}\) (1 ពិន្ទុ)
ដូចនេះ \(BC = 110\ \text{cm}\) (និង \(EF = 110\ \text{cm}\)) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'easy', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9138, 'អង្កត់ \(AB\) និង \(CD\) ប្រសព្វគ្នាត្រង់ចំណុចកណ្តាល \(E\) នៃអង្កត់នីមួយៗ (\(EA = EB\) និង \(EC = ED\))។ ក. ប្រៀបធៀបត្រីកោណ \(EAD\) និង \(EBC\)។ ខ. ទាញបញ្ជាក់ថា \(AD = BC\)។ គ. បង្ហាញថាអង្កត់ \(AD \parallel BC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុង \(\Delta EAD\) និង \(\Delta EBC\) មាន \(EA = EB\) និង \(ED = EC\) (1 ពិន្ទុ)
\(\angle AED = \angle BEC\) (មុំទល់កំពូល) នាំឱ្យ \(\Delta EAD \cong \Delta EBC\) (តាម ជ.ម.ជ) (1 ពិន្ទុ)
ខ. វិបាក ៖ ជ្រុងត្រូវគ្នាប៉ុនគ្នា នាំឱ្យ \(AD = BC\) (1 ពិន្ទុ)
គ. វិបាក ៖ មុំត្រូវគ្នា \(\angle EAD = \angle EBC\) (1 ពិន្ទុ)
ដោយមុំទាំងពីរជាមុំឆ្លាស់ក្នុង នាំឱ្យ \(AD \parallel BC\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9139, 'គេឱ្យរង្វាស់ជ្រុងបីករណី ៖ ក. \(11,\ 12,\ 17\) 	 ខ. \(1,\ 2,\ 3\) 	 គ. \(4.1,\ 4.7,\ 9\)។ ចំពោះករណីនីមួយៗ តើគេអាចគូសបានត្រីកោណមួយឬទេ? ព្រោះអ្វី?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(11 + 12 = 23 > 17\) (ផលបូកពីរជ្រុងធំជាងជ្រុងទីបី) នាំឱ្យអាចគូសបានត្រីកោណ (2 ពិន្ទុ)
ខ. \(1 + 2 = 3\) (ផលបូកស្មើជ្រុងទីបី ចំណុចរត់ត្រង់ជួរ) នាំឱ្យមិនអាចគូសបានត្រីកោណទេ (1 ពិន្ទុ)
គ. \(4.1 + 4.7 = 8.8 < 9\) (ផលបូកតូចជាងជ្រុងទីបី) នាំឱ្យមិនអាចគូសបានត្រីកោណទេ (2 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9140, '\(\Delta ABC\) ជាត្រីកោណសមបាតកំពូល \(A\) (\(AB = AC\))។ កម្ពស់គូសចេញពី \(B\) និង \(C\) កាត់ជ្រុង \(AC\) និង \(AB\) ត្រង់ \(D\) និង \(E\) រៀងគ្នា។ ក. បង្ហាញថា \(\Delta BDC\) និង \(\Delta CEB\) ជាត្រីកោណកែង។ ខ. បង្ហាញថា \(\Delta BDC \cong \Delta CEB\)។ គ. ទាញវិបាកថា \(BD = CE\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(BD \perp AC \Rightarrow \angle BDC = 90^\circ\) និង \(CE \perp AB \Rightarrow \angle CEB = 90^\circ\) (1 ពិន្ទុ)
ខ. ក្នុងត្រីកោណកែងទាំងពីរមាន អ៊ីប៉ូតេនុស \(BC\) ជាជ្រុងរួម (1 ពិន្ទុ)
មុំស្រួច \(\angle DCB = \angle EBC\) (មុំបាតនៃត្រីកោណសមបាត \(ABC\)) (1 ពិន្ទុ)
ដូចនេះ \(\Delta BDC \cong \Delta CEB\) (តាមលក្ខខណ្ឌ អ.ម) (1 ពិន្ទុ)
គ. វិបាក ៖ ជ្រុងត្រូវគ្នាប៉ុនគ្នា នាំឱ្យ \(BD = CE\) (កម្ពស់ទាំងពីរប៉ុនគ្នា) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9141, 'គេឱ្យចំណុច \(A\) មិននៅលើបន្ទាត់ \(\Delta\)។ \(AH \perp \Delta\) ត្រង់ \(H\)។ ចំណុច \(B\) និង \(C\) នៅលើ \(\Delta\) ដោយ \(HB = HC\)។ ក. ប្រៀបធៀបត្រីកោណកែង \(AHB\) និង \(AHC\)។ ខ. ទាញបញ្ជាក់ថា \(AB = AC\)។ គ. បញ្ជាក់ប្រភេទនៃ \(\Delta ABC\)។', 'g8-6dcdc9abdb.svg', '[]', 0, NULL, 5, 'writing', 'ក. ក្នុងត្រីកោណកែង \(AHB\) និង \(AHC\) មាន \(AH\) ជាជ្រុងរួម (1 ពិន្ទុ)
\(HB = HC\) (សម្មតិកម្ម) នាំឱ្យ \(\Delta AHB \cong \Delta AHC\) (តាម ជ.ម.ជ) (1 ពិន្ទុ)
ខ. វិបាក ៖ អ៊ីប៉ូតេនុសត្រូវគ្នាប៉ុនគ្នា នាំឱ្យ \(AB = AC\) (2 ពិន្ទុ)
គ. ដោយ \(AB = AC\) នោះ \(\Delta ABC\) ជាត្រីកោណសមបាតកំពូល \(A\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'medium', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9142, 'ក្នុង \(\Delta ABC\) មាន \(\angle A = 6x + 4^\circ\), \(\angle B = 7x + 12^\circ\) និង \(\angle C = 6x - 7^\circ\)។ ក. រកតម្លៃនៃ \(x\)។ ខ. គណនារង្វាស់មុំ \(\angle A, \angle B, \angle C\)។ គ. រៀបប្រវែងជ្រុងតាមលំដាប់ពីធំទៅតូច។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ផលបូកមុំក្នុង ៖ \((6x+4) + (7x+12) + (6x-7) = 180^\circ \Rightarrow 19x + 9 = 180\) (1 ពិន្ទុ)
\(19x = 171 \Rightarrow x = 9^\circ\) (1 ពិន្ទុ)
ខ. \(\angle A = 58^\circ\), \(\angle B = 75^\circ\), \(\angle C = 47^\circ\) (1 ពិន្ទុ)
គ. ដោយ \(\angle B > \angle A > \angle C\) នោះជ្រុងឈមធំជាង (1 ពិន្ទុ)
ដូចនេះ លំដាប់ជ្រុងពីធំទៅតូចគឺ \(AC > BC > AB\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9143, 'កន្លះបន្ទាត់ពុះនៃ \(\angle B\) និង \(\angle C\) ក្នុង \(\Delta ABC\) ប្រសព្វគ្នាត្រង់ \(I\)។ គូស \(ID \perp AB, IE \perp BC, IF \perp AC\)។ ក. បង្ហាញថា \(\Delta BDI \cong \Delta BEI\) រួចទាញថា \(ID = IE\)។ ខ. បង្ហាញថា \(IE = IF\)។ គ. ទាញបញ្ជាក់ថា \(AI\) ជាកន្លះបន្ទាត់ពុះនៃ \(\angle BAC\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(\Delta BDI \cong \Delta BEI\) (អ.ម ៖ អ៊ីប៉ូតេនុស \(BI\) រួម, \(\angle IBD = \angle IBE\)) នាំឱ្យ \(ID = IE\) (2 ពិន្ទុ)
ខ. ដូចគ្នា \(\Delta CEI \cong \Delta CFI\) (អ.ម) នាំឱ្យ \(IE = IF\) ដូចនេះ \(ID = IE = IF\) (1 ពិន្ទុ)
គ. ក្នុងត្រីកោណកែង \(IDA\) និង \(IFA\) មាន អ៊ីប៉ូតេនុស \(AI\) រួម និង \(ID = IF\) (1 ពិន្ទុ)
នាំឱ្យ \(\Delta IDA \cong \Delta IFA\) (អ.ជ) ទាញបាន \(\angle IAD = \angle IAF\) ដូចនេះ \(AI\) ជាកន្លះបន្ទាត់ពុះ (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9144, 'ចតុកោណ \(ABCD\) មាន \(AB = BC\) និង \(AD = CD\) (រាងខ្លែង)។ \(E\) ជាចំណុចនៅលើអង្កត់ទ្រូង \(BD\)។ ក. បង្ហាញថា \(\Delta ABD \cong \Delta CBD\)។ ខ. ទាញបញ្ជាក់ថា \(\angle ADE = \angle CDE\)។ គ. បង្ហាញថា \(\Delta AED \cong \Delta CED\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុង \(\Delta ABD\) និង \(\Delta CBD\) មាន \(AB = BC, AD = CD\) និង \(BD\) ជាជ្រុងរួម (1 ពិន្ទុ)
ដូចនេះ \(\Delta ABD \cong \Delta CBD\) (តាមលក្ខខណ្ឌ ជ.ជ.ជ) (1 ពិន្ទុ)
ខ. វិបាក ៖ មុំត្រូវគ្នាប៉ុនគ្នា នាំឱ្យ \(\angle ADB = \angle CDB\) ឬ \(\angle ADE = \angle CDE\) (1 ពិន្ទុ)
គ. ក្នុង \(\Delta AED\) និង \(\Delta CED\) មាន \(AD = CD\), \(\angle ADE = \angle CDE\) និង \(ED\) ជាជ្រុងរួម (1 ពិន្ទុ)
ដូចនេះ \(\Delta AED \cong \Delta CED\) (តាមលក្ខខណ្ឌ ជ.ម.ជ) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9145, 'គេឱ្យ \(AD, BE, CF\) ជាកម្ពស់ទាំងបីនៃត្រីកោណ \(ABC\)។ ក. ប្រៀបធៀបកម្ពស់ \(AD\) ជាមួយជ្រុង \(AB\)។ ខ. ប្រៀបធៀបកម្ពស់ \(BE\) ជាមួយ \(BC\) និង \(CF\) ជាមួយ \(AC\)។ គ. បង្ហាញថា \(AB + BC + AC > AD + BE + CF\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុងត្រីកោណកែង \(ADB\) អង្កត់កែងខ្លីជាងអ៊ីប៉ូតេនុស នាំឱ្យ \(AD < AB\) (1.5 ពិន្ទុ)
ខ. ដូចគ្នា ក្នុងត្រីកោណកែង \(BEC\) បាន \(BE < BC\) និងក្នុង \(CFA\) បាន \(CF < AC\) (1.5 ពិន្ទុ)
គ. បូកវិសមភាពទាំងបីអង្គនិងអង្គ ៖ \(AD + BE + CF < AB + BC + AC\) (1 ពិន្ទុ)
ឬ \(AB + BC + AC > AD + BE + CF\) (បរិមាត្រធំជាងផលបូកកម្ពស់ទាំងបី) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'hard', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9146, 'ដើម្បីវាស់ទទឹងស្ទឹងពីចំណុច \(A\) ទៅ \(B\) (\(AB \perp AC\)) វិស្វករដៅ \(O\) ជាចំណុចកណ្តាលនៃ \(AC\) (\(OA = OC\)) រួចដើរកែងនឹង \(AC\) ដល់ \(D\) ត្រង់ជួរនឹង \(B, O\) (ដូចរូប)។ ក. បង្ហាញថា \(\Delta OAB \cong \Delta OCD\)។ ខ. បញ្ជាក់ករណីប៉ុនគ្នា។ គ. បើវាស់បាន \(CD = 38\ \text{m}\) រកទទឹងស្ទឹង \(AB\)។', 'g8-39f837a312.svg', '[]', 0, NULL, 5, 'writing', 'ក. ក្នុង \(\Delta OAB\) និង \(\Delta OCD\) មាន \(\angle OAB = \angle OCD = 90^\circ\) និង \(OA = OC\) (1 ពិន្ទុ)
\(\angle AOB = \angle COD\) (មុំទល់កំពូល) (1 ពិន្ទុ)
ដូចនេះ \(\Delta OAB \cong \Delta OCD\) (1 ពិន្ទុ)
ខ. ត្រីកោណទាំងពីរប៉ុនគ្នាតាមករណី ម.ជ.ម (Angle-Side-Angle) (1 ពិន្ទុ)
គ. វិបាក ៖ \(AB = CD = 38\ \text{m}\) ដូចនេះទទឹងស្ទឹងគឺ \(38\ \text{m}\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9147, 'សុខាមានកំណាត់ឈើ ៤ ប្រវែង \(2\ \text{m},\ 4.5\ \text{m},\ 5.8\ \text{m},\ 10.2\ \text{m}\) សម្រាប់ធ្វើស៊ុមត្រីកោណព័ទ្ធសួនផ្កា។ ក. សរសេរបន្សំទាំង ៤ ដែលអាចរើសឈើ ៣ កំណាត់។ ខ. ពិនិត្យវិសមភាពត្រីកោណលើបន្សំនីមួយៗ។ គ. សន្និដ្ឋានចំនួនត្រីកោណដែលអាចបង្កើតបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. បន្សំទាំង ៤ ៖ \(\{2, 4.5, 5.8\},\ \{2, 4.5, 10.2\},\ \{2, 5.8, 10.2\},\ \{4.5, 5.8, 10.2\}\) (1 ពិន្ទុ)
ខ. \(\{2, 4.5, 5.8\} \colon 2 + 4.5 = 6.5 > 5.8\) (បានត្រីកោណ) (1 ពិន្ទុ)
\(\{2, 4.5, 10.2\} \colon 2 + 4.5 = 6.5 < 10.2\) (មិនបាន), \(\{2, 5.8, 10.2\} \colon 2 + 5.8 = 7.8 < 10.2\) (មិនបាន) (1 ពិន្ទុ)
\(\{4.5, 5.8, 10.2\} \colon 4.5 + 5.8 = 10.3 > 10.2\) (បានត្រីកោណ) (1 ពិន្ទុ)
គ. សន្និដ្ឋាន ៖ សុខាអាចបង្កើតត្រីកោណខុសៗគ្នាបានតែ 2 ប៉ុណ្ណោះ (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9148, 'គ្រោងដំបូលផ្ទះរាងត្រីកោណសមបាត \(ABC\) កំពូល \(A\) មានកម្ពស់ \(AH \perp BC\)។ ក. បង្ហាញថា \(\Delta AHB \cong \Delta AHC\) (តាម អ.ជ)។ ខ. ទាញបញ្ជាក់ថា \(H\) ជាចំណុចកណ្តាលនៃ \(BC\)។ គ. បើធ្នឹមបាត \(BC = 8\ \text{m}\) និងកម្ពស់ \(AH = 3\ \text{m}\) គណនាប្រវែងជើងធ្នឹម \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុងត្រីកោណកែងទាំងពីរមាន \(AH\) ជាជ្រុងរួម និងអ៊ីប៉ូតេនុស \(AB = AC\) (សមបាត) (1 ពិន្ទុ)
ដូចនេះ \(\Delta AHB \cong \Delta AHC\) (តាមលក្ខខណ្ឌ អ.ជ) (1 ពិន្ទុ)
ខ. វិបាក ៖ \(HB = HC = \dfrac{BC}{2} = \dfrac{8}{2} = 4\ \text{m}\) នាំឱ្យ \(H\) ជាចំណុចកណ្តាលនៃ \(BC\) (1 ពិន្ទុ)
គ. តាមទ្រឹស្តីបទពីតាករក្នុង \(\Delta AHB\) ៖ \(AB^2 = AH^2 + HB^2 = 3^2 + 4^2 = 9 + 16 = 25\) (1 ពិន្ទុ)
\(AB = \sqrt{25} = 5\ \text{m}\) ដូចនេះប្រវែងជើងធ្នឹមគឺ \(AB = AC = 5\ \text{m}\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9149, 'ក្នុងវិស្វកម្មសំណង់ គេតែងរៀបរចនាសម្ព័ន្ធដែកជាទម្រង់ត្រីកោណ (Truss Structure)។ ក. ពន្យល់ហេតុផលធរណីមាត្រតាមករណី ជ.ជ.ជ។ ខ. ប្រៀបធៀបរវាងស៊ុមចតុកោណ និងស៊ុមត្រីកោណ ពេលរងកម្លាំងរុញ។ គ. បញ្ជាក់វិធីធ្វើឱ្យស៊ុមចតុកោណរឹងមាំដូចត្រីកោណ។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. តាមករណី ជ.ជ.ជ កាលណាប្រវែងជ្រុងទាំងបីថេរ រូបរាងនិងមុំនៃត្រីកោណមិនអាចប្រែប្រួលរាងបានឡើយ (2 ពិន្ទុ)
ខ. ស៊ុមចតុកោណអាចបត់ទ្រេតទៅជាប្រលេឡូក្រាមពេលរងកម្លាំងពីចំហៀង ឯត្រីកោណរក្សារូបរាងដដែល (1 ពិន្ទុ)
គ. វិធីដោះស្រាយ ៖ គេដាក់អង្កត់ទ្រូងមួយខ្វែងកណ្តាលចតុកោណ (Cross-bracing) (1 ពិន្ទុ)
ដើម្បីបំបែកចតុកោណទៅជាត្រីកោណពីរដែលរឹងមាំទប់ទល់នឹងកម្លាំងរុញច្រាន (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 9150, 'សិស្សានុសិស្សចង់វាស់ចម្ងាយរវាងដើមឈើពីរដើម \(A\) និង \(B\) នៅត្រើយម្ខាងស្រះ។ ពួកគេដៅ \(O\) រួចបន្លាយ \(AO\) ឱ្យបាន \(OA'' = OA\) និងបន្លាយ \(BO\) ឱ្យបាន \(OB'' = OB\)។ ក. បង្ហាញថា \(\Delta OAB \cong \Delta OA''B''\)។ ខ. ទាញបញ្ជាក់ថា \(AB = A''B''\)។ គ. បើវាស់បាន \(A''B'' = 24.5\ \text{m}\) រកចម្ងាយ \(AB\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ក. ក្នុង \(\Delta OAB\) និង \(\Delta OA''B''\) មាន \(OA = OA''\) និង \(OB = OB''\) (1 ពិន្ទុ)
\(\angle AOB = \angle A''OB''\) (មុំទល់កំពូល) នាំឱ្យ \(\Delta OAB \cong \Delta OA''B''\) (តាម ជ.ម.ជ) (1 ពិន្ទុ)
ខ. វិបាក ៖ ជ្រុងត្រូវគ្នាប៉ុនរៀងគ្នា នាំឱ្យ \(AB = A''B''\) (1 ពិន្ទុ)
គ. ដោយវាស់បាន \(A''B'' = 24.5\ \text{m}\) នៅលើទីវាលស្ងួត (1 ពិន្ទុ)
ដូចនេះ ចម្ងាយរវាងដើមឈើទាំងពីរគឺ \(AB = 24.5\ \text{m}\) (1 ពិន្ទុ)', 'ការប្រៀបធៀបត្រីកោណ', 'pisa', 0, '8', 'ការប្រៀបធៀបត្រីកោណ', NULL, 0);
